describe("renderRegistry: gatoBranding in the client file", () => {
  const full = {
    name: "demo",
    hasModuleTs: true,
    hasEnv: true,
    hasAuth: true,
    hasAuthClient: true,
    hasAuditSink: true,
    hasEvents: false,
    hasSubscribers: false,
    hasSlots: false,
    hasClientSlots: false,
    hasComponents: false,
    hasCommandHooks: false,
    hasSetup: false,
    version: "1.0.0",
    locales: ["pl", "en"],
  };

  it("the client file ends with clientModules, clientModuleSlots, clientComponentOverrides and the gatoBranding line, with hasGatoConfig", () => {
    const lines = renderRegistry([full], BOTH, {
      hasGatoConfig: true,
    }).client.split("\n");
    expect(lines.slice(-5)).toEqual([
      "export const clientModules = applyGatoConfig([demoModule], gatoConfig);",
      "export const clientModuleSlots = clientSlotRegistry([], gatoConfig);",
      EMPTY_COMPONENT_OVERRIDES,
      BRANDING_EXPORT,
      "",
    ]);
  });

  it("the client file ends with clientModules, clientModuleSlots, clientComponentOverrides and the gatoBranding line, without hasGatoConfig", () => {
    const lines = renderRegistry([full], BOTH, {
      hasGatoConfig: false,
    }).client.split("\n");
    expect(lines.slice(-5)).toEqual([
      "export const clientModules = applyGatoConfig([demoModule], gatoConfig);",
      "export const clientModuleSlots = clientSlotRegistry([], gatoConfig);",
      EMPTY_COMPONENT_OVERRIDES,
      BRANDING_EXPORT,
      "",
    ]);
  });

  it("gatoBrandingOf is the last name of the helper import", () => {
    const { client } = renderRegistry([full], BOTH);
    expect(client.split("\n")[2]).toBe(CLIENT_ALL_HELPERS_IMPORT);
  });

  it("the client file declares gatoBranding exactly once", () => {
    const { client } = renderRegistry([full], BOTH, { hasGatoConfig: true });
    expect(
      client.split("\n").filter((line) => line.includes("gatoBranding ")),
    ).toEqual([BRANDING_EXPORT]);
  });

  it("the server file does not mention branding", () => {
    for (const hasGatoConfig of [true, false]) {
      for (const modules of [[], [full]]) {
        const { server } = renderRegistry(modules, BOTH, { hasGatoConfig });
        expect(server).not.toContain("gatoBranding");
      }
    }
  });

  test.prop([
    fc.array(
      fc.record({
        name: fc.stringMatching(/^[a-z][a-z0-9]*$/),
        hasModuleTs: fc.boolean(),
        hasEnv: fc.boolean(),
        hasAuth: fc.boolean(),
        hasAuthClient: fc.boolean(),
        hasAuditSink: fc.boolean(),
        hasEvents: fc.boolean(),
        hasSubscribers: fc.boolean(),
        hasSlots: fc.boolean(),
        hasClientSlots: fc.boolean(),
        hasComponents: fc.boolean(),
        hasCommandHooks: fc.boolean(),
        hasSetup: fc.boolean(),
        version: fc.constant("1.0.0"),
        locales: fc.constant<string[]>([]),
      }),
      { maxLength: 4 },
    ),
    fc.boolean(),
  ])(
    "every client file ends with the gatoBranding line and imports the config on line 2",
    (modules, hasGatoConfig) => {
      const lines = renderRegistry(modules, BOTH, {
        hasGatoConfig,
      }).client.split("\n");
      expect(lines.slice(-2)).toEqual([BRANDING_EXPORT, ""]);
      expect(lines[1]).toBe(
        hasGatoConfig ? CONFIG_IMPORT : EMPTY_CONFIG_IMPORT,
      );
      expect(lines[2]).toMatch(
        /^import \{ (?:[A-Za-z]+, )*gatoBrandingOf \} from "@\/shared\/lib\/modules\/gato-config";$/,
      );
    },
  );
});

describe("renderRegistry: moduleEvents and moduleSubscribers", () => {
  const SERVER_HELPERS_WITH_EVENTS_IMPORT =
    'import { applyGatoConfig, enabledEntries, enabledModuleEntries } from "@/shared/lib/modules/gato-config";';
  const invoices = {
    name: "invoices",
    ...base,
    hasModuleTs: true,
    hasAuditSink: true,
    hasEvents: true,
    hasSubscribers: true,
  };

  it("a module with events.ts and subscribers.ts gets both imports after the auditSink import and both lists after auditSinks", () => {
    expect(
      renderRegistry([invoices], ["pl"], { hasGatoConfig: true }).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        SERVER_HELPERS_WITH_EVENTS_IMPORT,
        'import { slotRegistry } from "@/shared/lib/modules/slots";',
        'import { commandHookRegistry } from "@/shared/lib/commands/define-command";',
        'import invoicesModule from "@/features/invoices/module";',
        'import { auditSink as invoicesAuditSink } from "@/features/invoices/audit-sink";',
        'import { events as invoicesEvents } from "@/features/invoices/events";',
        'import { subscribers as invoicesSubscribers } from "@/features/invoices/subscribers";',
        "",
        "export const modules = applyGatoConfig([invoicesModule], gatoConfig);",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        'export const auditSinks = enabledEntries([{ module: "invoices", value: invoicesAuditSink }], gatoConfig);',
        'export const moduleEvents = [{ module: "invoices", value: invoicesEvents }];',
        'export const moduleSubscribers = enabledModuleEntries([{ module: "invoices", value: invoicesSubscribers }], gatoConfig);',
        "export const moduleCommandHooks = commandHookRegistry({ modules: [invoicesModule], hooks: [] }, gatoConfig);",
        "export const moduleSetups: never[] = [];",
        "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("a module with only events.ts imports no helper, because moduleEvents is not filtered, but the config for moduleSlots", () => {
    expect(
      renderRegistry([{ name: "alpha", ...base, hasEvents: true }], ["pl"], {
        hasGatoConfig: true,
      }).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { slotRegistry } from "@/shared/lib/modules/slots";',
        'import { commandHookRegistry } from "@/shared/lib/commands/define-command";',
        'import { events as alphaEvents } from "@/features/alpha/events";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        'export const moduleEvents = [{ module: "alpha", value: alphaEvents }];',
        "export const moduleSubscribers: never[] = [];",
        "export const moduleCommandHooks = commandHookRegistry({ modules: [], hooks: [] }, gatoConfig);",
        "export const moduleSetups: never[] = [];",
        "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("a module with only subscribers.ts imports the config and only enabledModuleEntries", () => {
    expect(
      renderRegistry(
        [{ name: "beta", ...base, hasSubscribers: true }],
        ["pl"],
        { hasGatoConfig: false },
      ).server,
    ).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { enabledModuleEntries } from "@/shared/lib/modules/gato-config";',
        'import { slotRegistry } from "@/shared/lib/modules/slots";',
        'import { commandHookRegistry } from "@/shared/lib/commands/define-command";',
        'import { subscribers as betaSubscribers } from "@/features/beta/subscribers";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const moduleEvents: never[] = [];",
        'export const moduleSubscribers = enabledModuleEntries([{ module: "beta", value: betaSubscribers }], gatoConfig);',
        "export const moduleCommandHooks = commandHookRegistry({ modules: [], hooks: [] }, gatoConfig);",
        "export const moduleSetups: never[] = [];",
        "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("enabledModuleEntries sits after applyGatoConfig when enabledEntries is not used", () => {
    const lines = renderRegistry(
      [{ name: "alpha", ...base, hasModuleTs: true, hasSubscribers: true }],
      ["pl"],
      { hasGatoConfig: true },
    ).server.split("\n");
    expect(lines[4]).toBe(
      'import { applyGatoConfig, enabledModuleEntries } from "@/shared/lib/modules/gato-config";',
    );
  });

  it("enabledModuleEntries sits between enabledEntries and the end of the server helper import", () => {
    const lines = renderRegistry([invoices], BOTH).server.split("\n");
    expect(
      lines.filter((line) => line.includes("@/shared/lib/modules/gato-config")),
    ).toEqual([EMPTY_CONFIG_IMPORT, SERVER_HELPERS_WITH_EVENTS_IMPORT]);
  });

  it("with no module declaring events or subscribers both lists are never[] and no helper import names enabledModuleEntries", () => {
    const { server } = renderRegistry(
      [{ name: "alpha", ...base, hasModuleTs: true, hasEnv: true }],
      BOTH,
    );
    expect(server.split("\n")).toContain(
      "export const moduleEvents: never[] = [];",
    );
    expect(server.split("\n")).toContain(
      "export const moduleSubscribers: never[] = [];",
    );
    expect(server).not.toContain("enabledModuleEntries");
    expect(server).not.toContain("/events");
    expect(server).not.toContain("/subscribers");
  });

  it("several modules keep the input order in both lists and their imports", () => {
    const { server } = renderRegistry(
      [
        { name: "zeta", ...base, hasEvents: true, hasSubscribers: true },
        { name: "alpha", ...base, hasEvents: true, hasSubscribers: true },
      ],
      ["pl"],
      { hasGatoConfig: true },
    );
    const lines = server.split("\n");
    expect(lines).toContain(
      'export const moduleEvents = [{ module: "zeta", value: zetaEvents }, { module: "alpha", value: alphaEvents }];',
    );
    expect(lines).toContain(
      'export const moduleSubscribers = enabledModuleEntries([{ module: "zeta", value: zetaSubscribers }, { module: "alpha", value: alphaSubscribers }], gatoConfig);',
    );
    expect(
      lines.indexOf(
        'import { events as zetaEvents } from "@/features/zeta/events";',
      ),
    ).toBeLessThan(
      lines.indexOf(
        'import { events as alphaEvents } from "@/features/alpha/events";',
      ),
    );
    expect(
      lines.indexOf(
        'import { subscribers as zetaSubscribers } from "@/features/zeta/subscribers";',
      ),
    ).toBeLessThan(
      lines.indexOf(
        'import { subscribers as alphaSubscribers } from "@/features/alpha/subscribers";',
      ),
    );
  });

  it("a module enters only the lists of the files it has", () => {
    const { server } = renderRegistry(
      [
        { name: "alpha", ...base, hasEvents: true },
        { name: "beta", ...base, hasSubscribers: true },
      ],
      ["pl"],
      { hasGatoConfig: true },
    );
    const lines = server.split("\n");
    expect(lines).toContain(
      'export const moduleEvents = [{ module: "alpha", value: alphaEvents }];',
    );
    expect(lines).toContain(
      'export const moduleSubscribers = enabledModuleEntries([{ module: "beta", value: betaSubscribers }], gatoConfig);',
    );
    expect(server).not.toContain("@/features/alpha/subscribers");
    expect(server).not.toContain("@/features/beta/events");
  });

  it("a hyphenated module name gives camelCase identifiers and keeps the raw key", () => {
    const lines = renderRegistry(
      [
        {
          name: "my-feature",
          ...base,
          hasEvents: true,
          hasSubscribers: true,
        },
      ],
      ["pl"],
    ).server.split("\n");
    expect(lines).toContain(
      'import { events as myFeatureEvents } from "@/features/my-feature/events";',
    );
    expect(lines).toContain(
      'import { subscribers as myFeatureSubscribers } from "@/features/my-feature/subscribers";',
    );
    expect(lines).toContain(
      'export const moduleEvents = [{ module: "my-feature", value: myFeatureEvents }];',
    );
    expect(lines).toContain(
      'export const moduleSubscribers = enabledModuleEntries([{ module: "my-feature", value: myFeatureSubscribers }], gatoConfig);',
    );
  });

  it("moduleEvents is not wrapped in a config helper, so a disabled module keeps its schemas", () => {
    const { server } = renderRegistry([invoices], BOTH, {
      hasGatoConfig: true,
    });
    const eventsLines = server
      .split("\n")
      .filter((line) => line.startsWith("export const moduleEvents"));
    expect(eventsLines).toEqual([
      'export const moduleEvents = [{ module: "invoices", value: invoicesEvents }];',
    ]);
  });

  it("the client file says nothing about events or subscribers", () => {
    const withEvents = renderRegistry([invoices], BOTH, {
      hasGatoConfig: true,
    }).client;
    const withoutEvents = renderRegistry(
      [{ ...invoices, hasEvents: false, hasSubscribers: false }],
      BOTH,
      { hasGatoConfig: true },
    ).client;
    expect(withEvents).toBe(withoutEvents);
    expect(withEvents).not.toContain("events");
    expect(withEvents).not.toContain("Events");
    expect(withEvents).not.toContain("ubscribers");
    expect(withEvents).not.toContain("enabledModuleEntries");
  });

  test.prop([
    fc.array(
      fc.record({
        name: fc.stringMatching(/^[a-z][a-z0-9]*$/),
        hasModuleTs: fc.boolean(),
        hasEnv: fc.boolean(),
        hasAuth: fc.boolean(),
        hasAuthClient: fc.boolean(),
        hasAuditSink: fc.boolean(),
        hasEvents: fc.boolean(),
        hasSubscribers: fc.boolean(),
        hasSlots: fc.boolean(),
        hasClientSlots: fc.boolean(),
        hasComponents: fc.boolean(),
        hasCommandHooks: fc.boolean(),
        hasSetup: fc.boolean(),
        version: fc.constant("1.0.0"),
        locales: fc.constant<string[]>([]),
      }),
      { maxLength: 4 },
    ),
    fc.boolean(),
  ])(
    "every server file declares moduleEvents, moduleSubscribers, moduleCommandHooks, moduleSetups and moduleSlots once, between auditSinks and env",
    (modules, hasGatoConfig) => {
      const lines = renderRegistry(modules, BOTH, {
        hasGatoConfig,
      }).server.split("\n");
      const auditSinksAt = lines.findIndex((line) =>
        line.startsWith("export const auditSinks"),
      );
      expect(lines[auditSinksAt + 1]).toMatch(/^export const moduleEvents\b/);
      expect(lines[auditSinksAt + 2]).toMatch(
        /^export const moduleSubscribers\b/,
      );
      expect(lines[auditSinksAt + 3]).toMatch(
        /^export const moduleCommandHooks\b/,
      );
      expect(lines[auditSinksAt + 4]).toMatch(/^export const moduleSetups\b/);
      expect(lines[auditSinksAt + 5]).toMatch(/^export const moduleSlots\b/);
      expect(lines[auditSinksAt + 6]).toBe(
        "export const env = createEnv(moduleEnvSchemas);",
      );
      expect(
        lines.filter((line) => line.startsWith("export const moduleSetups")),
      ).toHaveLength(1);
      expect(
        lines.filter((line) => line.startsWith("export const moduleEvents")),
      ).toHaveLength(1);
      expect(
        lines.filter((line) =>
          line.startsWith("export const moduleSubscribers"),
        ),
      ).toHaveLength(1);
    },
  );
});

describe("renderRegistry: moduleSetups", () => {
  const notes = {
    name: "notes",
    ...base,
    hasModuleTs: true,
    hasSubscribers: true,
    hasSetup: true,
    version: "1.2.0",
  };
  const NOTES_SETUP_IMPORT =
    'import { setup as notesSetup } from "@/features/notes/setup";';
  const NOTES_SETUPS =
    'export const moduleSetups = enabledModuleEntries([{ module: "notes", version: "1.2.0", value: notesSetup }], gatoConfig);';

  it("a module with subscribers.ts and setup.ts imports its setup after the subscribers import and lists it with its version right after moduleCommandHooks", () => {
    expect(
      renderRegistry([notes], ["pl"], { hasGatoConfig: true }).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig, enabledModuleEntries } from "@/shared/lib/modules/gato-config";',
        'import { slotRegistry } from "@/shared/lib/modules/slots";',
        'import { commandHookRegistry } from "@/shared/lib/commands/define-command";',
        'import notesModule from "@/features/notes/module";',
        'import { subscribers as notesSubscribers } from "@/features/notes/subscribers";',
        NOTES_SETUP_IMPORT,
        "",
        "export const modules = applyGatoConfig([notesModule], gatoConfig);",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const moduleEvents: never[] = [];",
        'export const moduleSubscribers = enabledModuleEntries([{ module: "notes", value: notesSubscribers }], gatoConfig);',
        "export const moduleCommandHooks = commandHookRegistry({ modules: [notesModule], hooks: [] }, gatoConfig);",
        NOTES_SETUPS,
        "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("a module with only setup.ts still imports enabledModuleEntries and the config", () => {
    expect(
      renderRegistry(
        [{ name: "notes", ...base, hasSetup: true, version: "1.2.0" }],
        ["pl"],
        { hasGatoConfig: false },
      ).server,
    ).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { enabledModuleEntries } from "@/shared/lib/modules/gato-config";',
        'import { slotRegistry } from "@/shared/lib/modules/slots";',
        'import { commandHookRegistry } from "@/shared/lib/commands/define-command";',
        NOTES_SETUP_IMPORT,
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const moduleEvents: never[] = [];",
        "export const moduleSubscribers: never[] = [];",
        "export const moduleCommandHooks = commandHookRegistry({ modules: [], hooks: [] }, gatoConfig);",
        NOTES_SETUPS,
        "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("with no module declaring setup.ts moduleSetups is never[] right after moduleCommandHooks and nothing imports a setup", () => {
    const lines = renderRegistry(
      [{ ...notes, hasSetup: false }],
      BOTH,
    ).server.split("\n");
    const commandHooksAt = lines.findIndex((line) =>
      line.startsWith("export const moduleCommandHooks"),
    );
    expect(lines[commandHooksAt + 1]).toBe(
      "export const moduleSetups: never[] = [];",
    );
    expect(lines.filter((line) => line.includes("/setup"))).toEqual([]);
  });

  it("the setup import sits between the command hooks imports and the slots imports", () => {
    const lines = renderRegistry(
      [{ ...notes, hasCommandHooks: true, hasSlots: true }],
      ["pl"],
    ).server.split("\n");
    const subscribersImportAt = lines.indexOf(
      'import { subscribers as notesSubscribers } from "@/features/notes/subscribers";',
    );
    expect(lines.slice(subscribersImportAt, subscribersImportAt + 4)).toEqual([
      'import { subscribers as notesSubscribers } from "@/features/notes/subscribers";',
      'import { commandHooks as notesCommandHooks } from "@/features/notes/command-hooks";',
      NOTES_SETUP_IMPORT,
      'import * as notesSlots from "@/features/notes/slots";',
    ]);
  });

  it("without command hooks the setup import sits between the subscribers imports and the slots imports", () => {
    const lines = renderRegistry(
      [{ ...notes, hasSlots: true }],
      ["pl"],
    ).server.split("\n");
    const subscribersImportAt = lines.indexOf(
      'import { subscribers as notesSubscribers } from "@/features/notes/subscribers";',
    );
    expect(lines.slice(subscribersImportAt, subscribersImportAt + 3)).toEqual([
      'import { subscribers as notesSubscribers } from "@/features/notes/subscribers";',
      NOTES_SETUP_IMPORT,
      'import * as notesSlots from "@/features/notes/slots";',
    ]);
  });

  it("setup imports of several modules follow all subscribers imports, in input order", () => {
    const lines = renderRegistry(
      [
        { ...notes, name: "zeta" },
        { ...notes, name: "alpha" },
      ],
      ["pl"],
    ).server.split("\n");
    const firstSubscribersImportAt = lines.indexOf(
      'import { subscribers as zetaSubscribers } from "@/features/zeta/subscribers";',
    );
    expect(
      lines.slice(firstSubscribersImportAt, firstSubscribersImportAt + 4),
    ).toEqual([
      'import { subscribers as zetaSubscribers } from "@/features/zeta/subscribers";',
      'import { subscribers as alphaSubscribers } from "@/features/alpha/subscribers";',
      'import { setup as zetaSetup } from "@/features/zeta/setup";',
      'import { setup as alphaSetup } from "@/features/alpha/setup";',
    ]);
  });

  it("several modules keep the input order and each carries the version of its own manifest", () => {
    const lines = renderRegistry(
      [
        { name: "zeta", ...base, hasSetup: true, version: "0.3.1" },
        { name: "beta", ...base, hasSetup: false, version: "9.9.9" },
        { name: "alpha", ...base, hasSetup: true, version: "2.0.0" },
      ],
      ["pl"],
    ).server.split("\n");
    expect(lines).toContain(
      'export const moduleSetups = enabledModuleEntries([{ module: "zeta", version: "0.3.1", value: zetaSetup }, { module: "alpha", version: "2.0.0", value: alphaSetup }], gatoConfig);',
    );
    expect(lines).not.toContain(
      'import { setup as betaSetup } from "@/features/beta/setup";',
    );
  });

  it("a hyphenated module name gives a camelCase identifier and keeps the raw key", () => {
    const lines = renderRegistry(
      [{ name: "my-feature", ...base, hasSetup: true, version: "1.0.0" }],
      ["pl"],
    ).server.split("\n");
    expect(lines).toContain(
      'import { setup as myFeatureSetup } from "@/features/my-feature/setup";',
    );
    expect(lines).toContain(
      'export const moduleSetups = enabledModuleEntries([{ module: "my-feature", version: "1.0.0", value: myFeatureSetup }], gatoConfig);',
    );
  });

  it("the client file says nothing about setups", () => {
    const { client } = renderRegistry([notes], BOTH);
    expect(client).not.toContain("setup");
    expect(client).not.toContain("Setup");
  });

  test.prop([
    fc.stringMatching(
      /^(0|[1-9][0-9]{0,2})\.(0|[1-9][0-9]{0,2})\.(0|[1-9][0-9]{0,2})$/,
    ),
    fc.boolean(),
  ])(
    "the manifest version is written verbatim into the setup entry",
    (version, hasGatoConfig) => {
      const lines = renderRegistry(
        [{ name: "notes", ...base, hasSetup: true, version }],
        ["pl"],
        { hasGatoConfig },
      ).server.split("\n");
      expect(
        lines.filter((line) => line.startsWith("export const moduleSetups")),
      ).toEqual([
        `export const moduleSetups = enabledModuleEntries([{ module: "notes", version: "${version}", value: notesSetup }], gatoConfig);`,
      ]);
    },
  );
});

describe("renderRegistry: moduleSlots and clientModuleSlots", () => {
  const SLOT_REGISTRY_IMPORT =
    'import { slotRegistry } from "@/shared/lib/modules/slots";';
  const CLIENT_SLOT_REGISTRY_IMPORT =
    'import { clientSlotRegistry } from "@/shared/lib/modules/slots";';
  const EMPTY_MODULE_SLOTS =
    "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);";
  const EMPTY_CLIENT_MODULE_SLOTS =
    "export const clientModuleSlots = clientSlotRegistry([], gatoConfig);";
  const invoices = {
    name: "invoices",
    ...base,
    hasModuleTs: true,
    hasSubscribers: true,
    hasSlots: true,
    hasClientSlots: true,
    hasSetup: false,
    version: "1.0.0",
  };

  it("a module with slots.ts and client-slots.ts gets namespace imports after subscribers and both lists in moduleSlots", () => {
    expect(
      renderRegistry([invoices], ["pl"], { hasGatoConfig: true }).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig, enabledModuleEntries } from "@/shared/lib/modules/gato-config";',
        SLOT_REGISTRY_IMPORT,
        'import { commandHookRegistry } from "@/shared/lib/commands/define-command";',
        'import invoicesModule from "@/features/invoices/module";',
        'import { subscribers as invoicesSubscribers } from "@/features/invoices/subscribers";',
        'import * as invoicesSlots from "@/features/invoices/slots";',
        'import * as invoicesClientSlots from "@/features/invoices/client-slots";',
        "",
        "export const modules = applyGatoConfig([invoicesModule], gatoConfig);",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const moduleEvents: never[] = [];",
        'export const moduleSubscribers = enabledModuleEntries([{ module: "invoices", value: invoicesSubscribers }], gatoConfig);',
        "export const moduleCommandHooks = commandHookRegistry({ modules: [invoicesModule], hooks: [] }, gatoConfig);",
        "export const moduleSetups: never[] = [];",
        'export const moduleSlots = slotRegistry({ slots: [{ module: "invoices", value: invoicesSlots }], clientSlots: [{ module: "invoices", value: invoicesClientSlots }] }, gatoConfig);',
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("the client file imports only client-slots.ts after the module imports and lists it in clientModuleSlots", () => {
    expect(
      renderRegistry([invoices], ["pl"], { hasGatoConfig: true }).client,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import { applyGatoConfig, gatoBrandingOf } from "@/shared/lib/modules/gato-config";',
        CLIENT_SLOT_REGISTRY_IMPORT,
        COMPONENT_REGISTRY_IMPORT,
        'import invoicesModule from "@/features/invoices/module";',
        'import * as invoicesClientSlots from "@/features/invoices/client-slots";',
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules = applyGatoConfig([invoicesModule], gatoConfig);",
        'export const clientModuleSlots = clientSlotRegistry([{ module: "invoices", value: invoicesClientSlots }], gatoConfig);',
        EMPTY_COMPONENT_OVERRIDES,
        BRANDING_EXPORT,
        "",
      ].join("\n"),
    );
  });

  it("a module with only slots.ts imports the config and slotRegistry but no helper", () => {
    expect(
      renderRegistry([{ name: "alpha", ...base, hasSlots: true }], ["pl"], {
        hasGatoConfig: false,
      }).server,
    ).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        SLOT_REGISTRY_IMPORT,
        'import { commandHookRegistry } from "@/shared/lib/commands/define-command";',
        'import * as alphaSlots from "@/features/alpha/slots";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const moduleEvents: never[] = [];",
        "export const moduleSubscribers: never[] = [];",
        "export const moduleCommandHooks = commandHookRegistry({ modules: [], hooks: [] }, gatoConfig);",
        "export const moduleSetups: never[] = [];",
        'export const moduleSlots = slotRegistry({ slots: [{ module: "alpha", value: alphaSlots }], clientSlots: [] }, gatoConfig);',
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("a module with only slots.ts leaves the client file without its import and with an empty clientModuleSlots", () => {
    const { client } = renderRegistry(
      [{ name: "alpha", ...base, hasSlots: true }],
      ["pl"],
    );
    expect(client).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        BRANDING_ONLY_IMPORT,
        CLIENT_SLOT_REGISTRY_IMPORT,
        COMPONENT_REGISTRY_IMPORT,
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules: never[] = [];",
        EMPTY_CLIENT_MODULE_SLOTS,
        EMPTY_COMPONENT_OVERRIDES,
        BRANDING_EXPORT,
        "",
      ].join("\n"),
    );
  });

  it("a module with only client-slots.ts enters the clientSlots list of moduleSlots and clientModuleSlots", () => {
    const { server, client } = renderRegistry(
      [{ name: "beta", ...base, hasClientSlots: true }],
      ["pl"],
      { hasGatoConfig: true },
    );
    const serverLines = server.split("\n");
    expect(serverLines).toContain(
      'import * as betaClientSlots from "@/features/beta/client-slots";',
    );
    expect(serverLines).toContain(
      'export const moduleSlots = slotRegistry({ slots: [], clientSlots: [{ module: "beta", value: betaClientSlots }] }, gatoConfig);',
    );
    expect(server).not.toContain("@/features/beta/slots");
    expect(client.split("\n")).toContain(
      'export const clientModuleSlots = clientSlotRegistry([{ module: "beta", value: betaClientSlots }], gatoConfig);',
    );
  });

  it("with no module declaring slots both lists are empty and no feature slots file is imported", () => {
    const { server, client } = renderRegistry(
      [{ name: "alpha", ...base, hasModuleTs: true, hasEnv: true }],
      BOTH,
    );
    expect(server.split("\n")).toContain(EMPTY_MODULE_SLOTS);
    expect(client.split("\n")).toContain(EMPTY_CLIENT_MODULE_SLOTS);
    expect(server).not.toContain("@/features/alpha/slots");
    expect(server).not.toContain("@/features/alpha/client-slots");
    expect(client).not.toContain("@/features/alpha/client-slots");
  });

  it("several modules keep the input order in both lists and their imports, slots before client-slots", () => {
    const { server, client } = renderRegistry(
      [
        { name: "zeta", ...base, hasSlots: true, hasClientSlots: true },
        { name: "alpha", ...base, hasSlots: true, hasClientSlots: true },
      ],
      ["pl"],
      { hasGatoConfig: true },
    );
    const lines = server.split("\n");
    const zetaSlots = lines.indexOf(
      'import * as zetaSlots from "@/features/zeta/slots";',
    );
    const alphaSlots = lines.indexOf(
      'import * as alphaSlots from "@/features/alpha/slots";',
    );
    const zetaClientSlots = lines.indexOf(
      'import * as zetaClientSlots from "@/features/zeta/client-slots";',
    );
    const alphaClientSlots = lines.indexOf(
      'import * as alphaClientSlots from "@/features/alpha/client-slots";',
    );
    expect(zetaSlots).toBeGreaterThan(0);
    expect(alphaSlots).toBe(zetaSlots + 1);
    expect(zetaClientSlots).toBe(zetaSlots + 2);
    expect(alphaClientSlots).toBe(zetaSlots + 3);
    expect(lines).toContain(
      'export const moduleSlots = slotRegistry({ slots: [{ module: "zeta", value: zetaSlots }, { module: "alpha", value: alphaSlots }], clientSlots: [{ module: "zeta", value: zetaClientSlots }, { module: "alpha", value: alphaClientSlots }] }, gatoConfig);',
    );
    expect(client.split("\n")).toContain(
      'export const clientModuleSlots = clientSlotRegistry([{ module: "zeta", value: zetaClientSlots }, { module: "alpha", value: alphaClientSlots }], gatoConfig);',
    );
  });

  it("the slot imports follow the events and subscribers imports", () => {
    const lines = renderRegistry(
      [
        {
          name: "alpha",
          ...base,
          hasEvents: true,
          hasSubscribers: true,
          hasSlots: true,
          hasClientSlots: true,
          hasSetup: false,
          version: "1.0.0",
        },
      ],
      ["pl"],
    ).server.split("\n");
    const subscribersAt = lines.indexOf(
      'import { subscribers as alphaSubscribers } from "@/features/alpha/subscribers";',
    );
    expect(lines.slice(subscribersAt - 1, subscribersAt + 4)).toEqual([
      'import { events as alphaEvents } from "@/features/alpha/events";',
      'import { subscribers as alphaSubscribers } from "@/features/alpha/subscribers";',
      'import * as alphaSlots from "@/features/alpha/slots";',
      'import * as alphaClientSlots from "@/features/alpha/client-slots";',
      "",
    ]);
  });

  it("the client-slots imports of the client file follow every module import", () => {
    const lines = renderRegistry(
      [
        { name: "alpha", ...base, hasModuleTs: true, hasClientSlots: true },
        { name: "beta", ...base, hasModuleTs: true, hasAuthClient: true },
      ],
      ["pl"],
    ).client.split("\n");
    expect(lines.slice(3, 10)).toEqual([
      CLIENT_SLOT_REGISTRY_IMPORT,
      COMPONENT_REGISTRY_IMPORT,
      'import { authClientPlugin as betaAuthClientPlugin } from "@/features/beta/auth-client";',
      'import alphaModule from "@/features/alpha/module";',
      'import betaModule from "@/features/beta/module";',
      'import * as alphaClientSlots from "@/features/alpha/client-slots";',
      "",
    ]);
  });

  it("a hyphenated module name gives camelCase identifiers and keeps the raw key", () => {
    const { server, client } = renderRegistry(
      [{ name: "my-feature", ...base, hasSlots: true, hasClientSlots: true }],
      ["pl"],
    );
    const lines = server.split("\n");
    expect(lines).toContain(
      'import * as myFeatureSlots from "@/features/my-feature/slots";',
    );
    expect(lines).toContain(
      'import * as myFeatureClientSlots from "@/features/my-feature/client-slots";',
    );
    expect(lines).toContain(
      'export const moduleSlots = slotRegistry({ slots: [{ module: "my-feature", value: myFeatureSlots }], clientSlots: [{ module: "my-feature", value: myFeatureClientSlots }] }, gatoConfig);',
    );
    expect(client.split("\n")).toContain(
      'export const clientModuleSlots = clientSlotRegistry([{ module: "my-feature", value: myFeatureClientSlots }], gatoConfig);',
    );
  });

  it("slots.ts never reaches the client file", () => {
    const { client } = renderRegistry([invoices], BOTH, {
      hasGatoConfig: true,
    });
    expect(client).not.toContain("@/features/invoices/slots");
    expect(client).not.toContain("invoicesSlots");
    expect(client).not.toContain("slotRegistry(");
    expect(client).toContain("clientSlotRegistry(");
  });

  it("the server file imports slotRegistry once and never clientSlotRegistry", () => {
    const { server } = renderRegistry([invoices], BOTH);
    expect(
      server
        .split("\n")
        .filter((line) => line.includes("@/shared/lib/modules/slots")),
    ).toEqual([SLOT_REGISTRY_IMPORT]);
    expect(server).not.toContain("clientSlotRegistry");
  });

  test.prop([
    fc.array(
      fc.record({
        name: fc.stringMatching(/^[a-z][a-z0-9]*$/),
        hasModuleTs: fc.boolean(),
        hasEnv: fc.boolean(),
        hasAuth: fc.boolean(),
        hasAuthClient: fc.boolean(),
        hasAuditSink: fc.boolean(),
        hasEvents: fc.boolean(),
        hasSubscribers: fc.boolean(),
        hasSlots: fc.boolean(),
        hasClientSlots: fc.boolean(),
        hasComponents: fc.boolean(),
        hasCommandHooks: fc.boolean(),
        hasSetup: fc.boolean(),
        version: fc.constant("1.0.0"),
        locales: fc.constant<string[]>([]),
      }),
      { maxLength: 4 },
    ),
    fc.boolean(),
  ])(
    "every pair of files declares moduleSlots right after moduleSetups, moduleSetups right after moduleCommandHooks and clientModuleSlots right after clientModules, and imports the config on line 2",
    (modules, hasGatoConfig) => {
      const { server, client } = renderRegistry(modules, BOTH, {
        hasGatoConfig,
      });
      const configImport = hasGatoConfig ? CONFIG_IMPORT : EMPTY_CONFIG_IMPORT;
      const serverLines = server.split("\n");
      const clientLines = client.split("\n");
      expect(serverLines[1]).toBe(configImport);
      expect(clientLines[1]).toBe(configImport);
      const commandHooksAt = serverLines.findIndex((line) =>
        line.startsWith("export const moduleCommandHooks"),
      );
      expect(serverLines[commandHooksAt - 1]).toMatch(
        /^export const moduleSubscribers\b/,
      );
      expect(serverLines[commandHooksAt]).toMatch(
        /^export const moduleCommandHooks = commandHookRegistry\(\{ modules: \[.*\], hooks: \[.*\] \}, gatoConfig\);$/,
      );
      expect(serverLines[commandHooksAt + 1]).toMatch(
        /^export const moduleSetups\b/,
      );
      expect(serverLines[commandHooksAt + 2]).toMatch(
        /^export const moduleSlots = slotRegistry\(\{ slots: \[.*\], clientSlots: \[.*\] \}, gatoConfig\);$/,
      );
      expect(
        serverLines.filter((line) =>
          line.startsWith("export const moduleSlots"),
        ),
      ).toHaveLength(1);
      const clientModulesAt = clientLines.findIndex((line) =>
        line.startsWith("export const clientModules"),
      );
      expect(clientLines[clientModulesAt + 1]).toMatch(
        /^export const clientModuleSlots = clientSlotRegistry\(\[.*\], gatoConfig\);$/,
      );
      expect(clientLines[clientModulesAt + 2]).toMatch(
        /^export const clientComponentOverrides = componentOverrideRegistry\(\[.*\], gatoConfig\);$/,
      );
      expect(clientLines[clientModulesAt + 3]).toBe(BRANDING_EXPORT);
      expect(clientLines[3]).toBe(CLIENT_SLOT_REGISTRY_IMPORT);
      expect(clientLines[4]).toBe(COMPONENT_REGISTRY_IMPORT);
    },
  );
});

describe("renderRegistry: clientComponentOverrides", () => {
  const CLIENT_SLOT_REGISTRY_IMPORT =
    'import { clientSlotRegistry } from "@/shared/lib/modules/slots";';
  const invoices = {
    name: "invoices",
    ...base,
    hasModuleTs: true,
    hasClientSlots: true,
    hasComponents: true,
  };

  it("a module with components.ts gets a namespace import after its client-slots import and an entry in clientComponentOverrides", () => {
    expect(
      renderRegistry([invoices], ["pl"], { hasGatoConfig: true }).client,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import { applyGatoConfig, gatoBrandingOf } from "@/shared/lib/modules/gato-config";',
        CLIENT_SLOT_REGISTRY_IMPORT,
        COMPONENT_REGISTRY_IMPORT,
        'import invoicesModule from "@/features/invoices/module";',
        'import * as invoicesClientSlots from "@/features/invoices/client-slots";',
        'import * as invoicesComponents from "@/features/invoices/components";',
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules = applyGatoConfig([invoicesModule], gatoConfig);",
        'export const clientModuleSlots = clientSlotRegistry([{ module: "invoices", value: invoicesClientSlots }], gatoConfig);',
        'export const clientComponentOverrides = componentOverrideRegistry([{ module: "invoices", value: invoicesComponents }], gatoConfig);',
        BRANDING_EXPORT,
        "",
      ].join("\n"),
    );
  });

  it("a module with only components.ts imports only gatoBrandingOf as a helper and enters clientComponentOverrides unfiltered", () => {
    expect(
      renderRegistry([{ name: "alpha", ...base, hasComponents: true }], ["pl"])
        .client,
    ).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        BRANDING_ONLY_IMPORT,
        CLIENT_SLOT_REGISTRY_IMPORT,
        COMPONENT_REGISTRY_IMPORT,
        'import * as alphaComponents from "@/features/alpha/components";',
        "",
        "export const authClientPlugins: never[] = [];",
        "export const clientModules: never[] = [];",
        "export const clientModuleSlots = clientSlotRegistry([], gatoConfig);",
        'export const clientComponentOverrides = componentOverrideRegistry([{ module: "alpha", value: alphaComponents }], gatoConfig);',
        BRANDING_EXPORT,
        "",
      ].join("\n"),
    );
  });

  it("without components.ts clientComponentOverrides is built from an empty list", () => {
    const { client } = renderRegistry(
      [{ name: "alpha", ...base, hasModuleTs: true, hasClientSlots: true }],
      ["pl"],
    );
    expect(client.split("\n")).toContain(EMPTY_COMPONENT_OVERRIDES);
    expect(client).not.toContain("@/features/alpha/components");
  });

  it("the server file is the same with and without components.ts and never mentions component overrides", () => {
    const withComponents = renderRegistry([invoices], BOTH, {
      hasGatoConfig: true,
    }).server;
    const withoutComponents = renderRegistry(
      [{ ...invoices, hasComponents: false }],
      BOTH,
      { hasGatoConfig: true },
    ).server;
    expect(withComponents).toBe(withoutComponents);
    expect(withComponents).not.toContain("@/features/invoices/components");
    expect(withComponents).not.toContain("invoicesComponents");
    expect(withComponents).not.toContain("componentOverrideRegistry");
    expect(withComponents).not.toContain("component-overrides");
    expect(withComponents).not.toContain("clientComponentOverrides");
  });

  it("with no modules at all the server file has no component line", () => {
    expect(renderRegistry([], BOTH).server).not.toContain("omponent");
  });

  it("several modules keep the input order in the list and their imports, all components imports after all client-slots imports", () => {
    const lines = renderRegistry(
      [
        { name: "zeta", ...base, hasClientSlots: true, hasComponents: true },
        { name: "alpha", ...base, hasClientSlots: true, hasComponents: true },
      ],
      ["pl"],
      { hasGatoConfig: true },
    ).client.split("\n");
    const zetaClientSlots = lines.indexOf(
      'import * as zetaClientSlots from "@/features/zeta/client-slots";',
    );
    expect(zetaClientSlots).toBeGreaterThan(0);
    expect(lines.slice(zetaClientSlots, zetaClientSlots + 5)).toEqual([
      'import * as zetaClientSlots from "@/features/zeta/client-slots";',
      'import * as alphaClientSlots from "@/features/alpha/client-slots";',
      'import * as zetaComponents from "@/features/zeta/components";',
      'import * as alphaComponents from "@/features/alpha/components";',
      "",
    ]);
    expect(lines).toContain(
      'export const clientComponentOverrides = componentOverrideRegistry([{ module: "zeta", value: zetaComponents }, { module: "alpha", value: alphaComponents }], gatoConfig);',
    );
  });

  it("a module enters clientComponentOverrides only when it has components.ts", () => {
    const { client } = renderRegistry(
      [
        { name: "alpha", ...base, hasModuleTs: true },
        { name: "beta", ...base, hasComponents: true },
      ],
      ["pl"],
    );
    expect(client.split("\n")).toContain(
      'export const clientComponentOverrides = componentOverrideRegistry([{ module: "beta", value: betaComponents }], gatoConfig);',
    );
    expect(client).not.toContain("@/features/alpha/components");
  });

  it("a hyphenated module name gives a camelCase identifier and keeps the raw key", () => {
    const lines = renderRegistry(
      [{ name: "my-feature", ...base, hasComponents: true }],
      ["pl"],
    ).client.split("\n");
    expect(lines).toContain(
      'import * as myFeatureComponents from "@/features/my-feature/components";',
    );
    expect(lines).toContain(
      'export const clientComponentOverrides = componentOverrideRegistry([{ module: "my-feature", value: myFeatureComponents }], gatoConfig);',
    );
  });

  it("the client file imports componentOverrideRegistry once", () => {
    const { client } = renderRegistry(
      [invoices, { name: "beta", ...base, hasComponents: true }],
      BOTH,
    );
    expect(
      client
        .split("\n")
        .filter((line) =>
          line.includes("@/shared/lib/modules/component-overrides"),
        ),
    ).toEqual([COMPONENT_REGISTRY_IMPORT]);
    expect(
      client
        .split("\n")
        .filter((line) =>
          line.startsWith("export const clientComponentOverrides"),
        ),
    ).toHaveLength(1);
  });

  test.prop([
    fc.array(
      fc.record({
        name: fc.stringMatching(/^[a-z][a-z0-9]*$/),
        hasModuleTs: fc.boolean(),
        hasEnv: fc.boolean(),
        hasAuth: fc.boolean(),
        hasAuthClient: fc.boolean(),
        hasAuditSink: fc.boolean(),
        hasEvents: fc.boolean(),
        hasSubscribers: fc.boolean(),
        hasSlots: fc.boolean(),
        hasClientSlots: fc.boolean(),
        hasComponents: fc.boolean(),
        hasCommandHooks: fc.boolean(),
        hasSetup: fc.boolean(),
        version: fc.constant("1.0.0"),
        locales: fc.constant<string[]>([]),
      }),
      { maxLength: 4 },
    ),
    fc.boolean(),
  ])(
    "every client file declares clientComponentOverrides once, right after clientModuleSlots and before gatoBranding, and the server file never mentions it",
    (modules, hasGatoConfig) => {
      const { server, client } = renderRegistry(modules, BOTH, {
        hasGatoConfig,
      });
      const lines = client.split("\n");
      const slotsAt = lines.findIndex((line) =>
        line.startsWith("export const clientModuleSlots"),
      );
      expect(lines[slotsAt + 1]).toMatch(
        /^export const clientComponentOverrides = componentOverrideRegistry\(\[.*\], gatoConfig\);$/,
      );
      expect(lines[slotsAt + 2]).toBe(BRANDING_EXPORT);
      expect(lines[4]).toBe(COMPONENT_REGISTRY_IMPORT);
      expect(
        lines.filter((line) =>
          line.startsWith("export const clientComponentOverrides"),
        ),
      ).toHaveLength(1);
      expect(server).not.toContain("componentOverrideRegistry");
      expect(server).not.toContain("Components");
    },
  );
});

describe("renderRegistry: moduleCommandHooks", () => {
  const COMMAND_HOOK_REGISTRY_IMPORT =
    'import { commandHookRegistry } from "@/shared/lib/commands/define-command";';
  const EMPTY_COMMAND_HOOKS =
    "export const moduleCommandHooks = commandHookRegistry({ modules: [], hooks: [] }, gatoConfig);";

  it("a module with module.ts and command-hooks.ts gets the hooks import after the module imports and enters both lists of moduleCommandHooks", () => {
    expect(
      renderRegistry(
        [
          {
            name: "invoices",
            ...base,
            hasModuleTs: true,
            hasCommandHooks: true,
          },
        ],
        ["pl"],
        { hasGatoConfig: true },
      ).server,
    ).toBe(
      [
        HEADER,
        CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { applyGatoConfig } from "@/shared/lib/modules/gato-config";',
        'import { slotRegistry } from "@/shared/lib/modules/slots";',
        COMMAND_HOOK_REGISTRY_IMPORT,
        'import invoicesModule from "@/features/invoices/module";',
        'import { commandHooks as invoicesCommandHooks } from "@/features/invoices/command-hooks";',
        "",
        "export const modules = applyGatoConfig([invoicesModule], gatoConfig);",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const moduleEvents: never[] = [];",
        "export const moduleSubscribers: never[] = [];",
        'export const moduleCommandHooks = commandHookRegistry({ modules: [invoicesModule], hooks: [{ module: "invoices", value: invoicesCommandHooks }] }, gatoConfig);',
        "export const moduleSetups: never[] = [];",
        "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("a module with only command-hooks.ts enters hooks but not modules and imports no config helper", () => {
    expect(
      renderRegistry(
        [{ name: "alpha", ...base, hasCommandHooks: true }],
        ["pl"],
        { hasGatoConfig: false },
      ).server,
    ).toBe(
      [
        HEADER,
        EMPTY_CONFIG_IMPORT,
        'import type { Locale } from "@/i18n/config";',
        'import { createEnv } from "@gatojs/env";',
        'import { slotRegistry } from "@/shared/lib/modules/slots";',
        COMMAND_HOOK_REGISTRY_IMPORT,
        'import { commandHooks as alphaCommandHooks } from "@/features/alpha/command-hooks";',
        "",
        "export const modules: never[] = [];",
        "export const moduleEnvSchemas: never[] = [];",
        "export const authPlugins: never[] = [];",
        "export const auditSinks: never[] = [];",
        "export const moduleEvents: never[] = [];",
        "export const moduleSubscribers: never[] = [];",
        'export const moduleCommandHooks = commandHookRegistry({ modules: [], hooks: [{ module: "alpha", value: alphaCommandHooks }] }, gatoConfig);',
        "export const moduleSetups: never[] = [];",
        "export const moduleSlots = slotRegistry({ slots: [], clientSlots: [] }, gatoConfig);",
        "export const env = createEnv(moduleEnvSchemas);",
        "",
        "export type MessageLoader = { key: string; load: () => Promise<Record<string, unknown>> };",
        "",
        "export const moduleMessages: Record<Locale, MessageLoader[]> = {",
        "  pl: [],",
        "};",
        "",
      ].join("\n"),
    );
  });

  it("with no modules moduleCommandHooks is still emitted with two empty lists", () => {
    const lines = renderRegistry([], ["pl"]).server.split("\n");
    expect(lines).toContain(COMMAND_HOOK_REGISTRY_IMPORT);
    expect(lines).toContain(EMPTY_COMMAND_HOOKS);
  });

  it("a module with module.ts and no command-hooks.ts enters modules but leaves hooks empty and imports no hooks file", () => {
    const { server } = renderRegistry(
      [{ name: "alpha", ...base, hasModuleTs: true, hasSubscribers: true }],
      ["pl"],
    );
    expect(server.split("\n")).toContain(
      "export const moduleCommandHooks = commandHookRegistry({ modules: [alphaModule], hooks: [] }, gatoConfig);",
    );
    expect(server).not.toContain("command-hooks");
    expect(server).not.toContain("alphaCommandHooks");
  });

  it("modules lists every module.ts identifier in input order and hooks only the modules with command-hooks.ts", () => {
    const { server } = renderRegistry(
      [
        { name: "zeta", ...base, hasModuleTs: true, hasCommandHooks: true },
        { name: "mid", ...base, hasModuleTs: true },
        { name: "alpha", ...base, hasCommandHooks: true },
        { name: "beta", ...base, hasModuleTs: true, hasCommandHooks: true },
      ],
      ["pl"],
      { hasGatoConfig: true },
    );
    const lines = server.split("\n");
    expect(lines).toContain(
      'export const moduleCommandHooks = commandHookRegistry({ modules: [zetaModule, midModule, betaModule], hooks: [{ module: "zeta", value: zetaCommandHooks }, { module: "alpha", value: alphaCommandHooks }, { module: "beta", value: betaCommandHooks }] }, gatoConfig);',
    );
    const zetaAt = lines.indexOf(
      'import { commandHooks as zetaCommandHooks } from "@/features/zeta/command-hooks";',
    );
    expect(zetaAt).toBeGreaterThan(0);
    expect(lines.slice(zetaAt, zetaAt + 4)).toEqual([
      'import { commandHooks as zetaCommandHooks } from "@/features/zeta/command-hooks";',
      'import { commandHooks as alphaCommandHooks } from "@/features/alpha/command-hooks";',
      'import { commandHooks as betaCommandHooks } from "@/features/beta/command-hooks";',
      "",
    ]);
    expect(server).not.toContain("@/features/mid/command-hooks");
  });

  it("the command hooks imports follow the subscribers imports and precede the slot imports", () => {
    const lines = renderRegistry(
      [
        {
          name: "alpha",
          ...base,
          hasEvents: true,
          hasSubscribers: true,
          hasCommandHooks: true,
          hasSlots: true,
          hasClientSlots: true,
        },
      ],
      ["pl"],
    ).server.split("\n");
    const eventsAt = lines.indexOf(
      'import { events as alphaEvents } from "@/features/alpha/events";',
    );
    expect(lines.slice(eventsAt, eventsAt + 6)).toEqual([
      'import { events as alphaEvents } from "@/features/alpha/events";',
      'import { subscribers as alphaSubscribers } from "@/features/alpha/subscribers";',
      'import { commandHooks as alphaCommandHooks } from "@/features/alpha/command-hooks";',
      'import * as alphaSlots from "@/features/alpha/slots";',
      'import * as alphaClientSlots from "@/features/alpha/client-slots";',
      "",
    ]);
  });

  it("the commandHookRegistry import sits right after the slotRegistry import, whatever the helper import", () => {
    const lines = renderRegistry(
      [
        {
          name: "alpha",
          ...base,
          hasModuleTs: true,
          hasEnv: true,
          hasSubscribers: true,
          hasCommandHooks: true,
        },
      ],
      BOTH,
    ).server.split("\n");
    expect(lines.slice(4, 8)).toEqual([
      'import { applyGatoConfig, enabledEntries, enabledModuleEntries } from "@/shared/lib/modules/gato-config";',
      'import { slotRegistry } from "@/shared/lib/modules/slots";',
      COMMAND_HOOK_REGISTRY_IMPORT,
      'import alphaModule from "@/features/alpha/module";',
    ]);
  });

  it("a hyphenated module name gives a camelCase identifier and keeps the raw key", () => {
    const lines = renderRegistry(
      [
        {
          name: "my-feature",
          ...base,
          hasModuleTs: true,
          hasCommandHooks: true,
        },
      ],
      ["pl"],
    ).server.split("\n");
    expect(lines).toContain(
      'import { commandHooks as myFeatureCommandHooks } from "@/features/my-feature/command-hooks";',
    );
    expect(lines).toContain(
      'export const moduleCommandHooks = commandHookRegistry({ modules: [myFeatureModule], hooks: [{ module: "my-feature", value: myFeatureCommandHooks }] }, gatoConfig);',
    );
  });

  it("the server file imports commandHookRegistry once, from define-command, and never run-command", () => {
    const { server } = renderRegistry(
      [
        { name: "alpha", ...base, hasModuleTs: true, hasCommandHooks: true },
        { name: "beta", ...base, hasModuleTs: true, hasCommandHooks: true },
      ],
      BOTH,
    );
    expect(
      server
        .split("\n")
        .filter((line) => line.includes("@/shared/lib/commands")),
    ).toEqual([COMMAND_HOOK_REGISTRY_IMPORT]);
    expect(server).not.toContain("run-command");
    expect(
      server
        .split("\n")
        .filter((line) => line.startsWith("export const moduleCommandHooks")),
    ).toHaveLength(1);
  });

  it("the client file says nothing about command hooks", () => {
    const withHooks = renderRegistry(
      [
        {
          name: "invoices",
          ...base,
          hasModuleTs: true,
          hasAuthClient: true,
          hasCommandHooks: true,
        },
      ],
      BOTH,
      { hasGatoConfig: true },
    ).client;
    const withoutHooks = renderRegistry(
      [
        {
          name: "invoices",
          ...base,
          hasModuleTs: true,
          hasAuthClient: true,
        },
      ],
      BOTH,
      { hasGatoConfig: true },
    ).client;
    expect(withHooks).toBe(withoutHooks);
    expect(withHooks).not.toContain("command-hooks");
    expect(withHooks).not.toContain("CommandHooks");
    expect(withHooks).not.toContain("commandHookRegistry");
    expect(withHooks).not.toContain("@/shared/lib/commands");
  });

  test.prop([
    fc.uniqueArray(
      fc.record({
        name: fc.stringMatching(/^[a-z][a-z0-9]*$/),
        hasModuleTs: fc.boolean(),
        hasEnv: fc.boolean(),
        hasAuth: fc.boolean(),
        hasAuthClient: fc.boolean(),
        hasAuditSink: fc.boolean(),
        hasEvents: fc.boolean(),
        hasSubscribers: fc.boolean(),
        hasSlots: fc.boolean(),
        hasClientSlots: fc.boolean(),
        hasCommandHooks: fc.boolean(),
        hasComponents: fc.boolean(),
        hasSetup: fc.boolean(),
        version: fc.constant("1.0.0"),
        locales: fc.constant<string[]>([]),
      }),
      { maxLength: 4, selector: (module) => module.name },
    ),
    fc.boolean(),
  ])(
    "every server file passes moduleCommandHooks the same module identifiers as modules, and one hook entry per imported hooks file",
    (modules, hasGatoConfig) => {
      const lines = renderRegistry(modules, BOTH, {
        hasGatoConfig,
      }).server.split("\n");
      const modulesLine =
        lines.find((line) => line.startsWith("export const modules")) ?? "";
      const listed =
        /^export const modules = applyGatoConfig\(\[(.*)\], gatoConfig\);$/.exec(
          modulesLine,
        )?.[1] ?? "";
      const hooksLine =
        lines.find((line) =>
          line.startsWith("export const moduleCommandHooks"),
        ) ?? "";
      expect(
        hooksLine.startsWith(
          `export const moduleCommandHooks = commandHookRegistry({ modules: [${listed}], hooks: [`,
        ),
      ).toBe(true);
      expect(hooksLine.endsWith("] }, gatoConfig);")).toBe(true);
      const imported = lines.filter((line) =>
        /^import \{ commandHooks as [A-Za-z0-9]+CommandHooks \} from "@\/features\/[a-z0-9]+\/command-hooks";$/.test(
          line,
        ),
      );
      expect(hooksLine.split("{ module: ").length - 1).toBe(imported.length);
    },
  );
});
